<script setup lang="ts">
import { Check, CircleHelp, Cpu, Layers3, RefreshCw, Search, ShieldCheck, X } from 'lucide-vue-next';
import { useConsole } from '../composables/useConsole';
import { dateText, rulePattern, splitRules } from '../utils/format';
const workspace = useConsole();
</script>
<template>
  <section class="panel"><div class="model-toolbar"><label>上游账号<select v-model="workspace.accountId"><option value="" disabled>请选择账号</option><option v-for="row in workspace.upstreams" :key="row.id" :value="row.id">{{ row.name }}</option></select></label><div class="model-freshness"><span>最近刷新</span><strong>{{ dateText(workspace.account?.models_refreshed_at) }}</strong></div><button class="button secondary" :disabled="!workspace.account || workspace.busy === 'refresh'" @click="workspace.refreshModels"><RefreshCw :size="16" :class="{ spinning: workspace.busy === 'refresh' }" />刷新目录</button></div></section><div v-if="workspace.account?.models_error" class="notice error" role="alert">{{ workspace.account.models_error }}</div>
  <div v-if="workspace.account" class="models-layout"><section class="panel"><header class="panel-header"><div><h3>账号模型目录 <span class="count-badge">{{ workspace.account.models.length }}</span></h3><p>勾选要加入白名单的模型</p></div><button class="text-button" @click="workspace.selectVisibleModels">选择搜索结果</button></header><div class="search-input model-search"><Search :size="17" /><input v-model="workspace.modelSearch" aria-label="搜索模型" placeholder="搜索模型名称…" /></div><div class="model-list"><label v-for="model in workspace.catalog" :key="model.id" class="model-option"><input v-model="workspace.modelDraft" type="checkbox" :value="model.id" /><span class="model-symbol"><Cpu :size="17" /></span><span>{{ model.id }}</span><Check v-if="workspace.modelDraft.includes(model.id)" :size="15" /></label><div v-if="!workspace.catalog.length" class="empty-state"><Layers3 :size="30" /><h3>暂无匹配模型</h3><p>刷新模型目录，或在右侧手工添加。</p></div></div></section><section class="panel whitelist-panel"><header class="panel-header"><div><h3>有效白名单</h3><p>{{ workspace.modelDraft.length }} 个精确模型已选中</p></div><ShieldCheck :size="18" /></header><div class="form-stack"><div v-if="workspace.modelDraft.length" class="selected-models"><span v-for="model in workspace.modelDraft" :key="model">{{ model }}<button :aria-label="`移除 ${model}`" @click="workspace.modelDraft = workspace.modelDraft.filter(item => item !== model)"><X :size="12" /></button></span></div><label>手工添加 / 前缀规则<textarea v-model="workspace.manualModels" class="mono" rows="6" placeholder="claude-*&#10;zai-org/GLM-5.3" /><small>每行一个模型名称或尾部 * 前缀规则。</small><small v-if="splitRules(workspace.manualModels).some(rule => !rulePattern.test(rule))" class="field-error">有无法识别的模型规则</small></label><div class="notice"><CircleHelp :size="17" /><span>空白名单表示不限制模型。出口 key 自己的白名单仍会生效。</span></div><button class="button primary full-width" :disabled="workspace.busy === 'models'" @click="workspace.saveModels"><Check :size="17" />{{ workspace.busy === 'models' ? '正在保存…' : '保存白名单' }}</button><button class="text-button centered" @click="workspace.modelDraft = []; workspace.manualModels = ''">清空选择（不限制）</button></div></section></div><div v-else class="panel empty-state"><Layers3 :size="32" /><h3>先添加一个上游账号</h3><button class="button secondary" @click="workspace.navigate('upstreams')">前往上游账号</button></div>
